// Unit tests for codec.mjs. Static. No emulator import.
// Stops at the first failed assertion. Do not edit this file after it has run.
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import {
  BANKS, CRC_BITS, DIM_H, DIM_V, FIELD_BITS, MARKER, MIRROR_BYTES, PAD_BITS,
  POSITION_MAX, PROFILE_A, RECORD_BYTES, STEP_H, STEP_V, USED_BYTES, VERSION, ZONE,
  crc16, decode, encode, mirrorFromProfile, profileFromMirror,
} from './codec.mjs';

const doc = JSON.parse(readFileSync('work/out/ranges-t10c.json', 'utf8'));
function tableOf(ui) {
  const row = doc.descriptors.find((r) => r.ui === ui);
  assert.ok(row && row.records.length === 1, 'ui ' + ui);
  const values = row.records[0].table.values_head;
  assert.equal(row.records[0].table.values_truncated, false);
  return values;
}
assert.deepEqual(tableOf(1333), ZONE);
assert.deepEqual(tableOf(1645), ZONE);
assert.deepEqual(tableOf(1643), ZONE);
assert.deepEqual(tableOf(1657), DIM_V);
assert.deepEqual(tableOf(1659), DIM_V);
assert.deepEqual(tableOf(1658), DIM_H);
assert.deepEqual(tableOf(1660), DIM_H);
assert.deepEqual(tableOf(1667), STEP_V);
assert.deepEqual(tableOf(1668), STEP_H);
const pos = doc.descriptors.find((r) => r.ui === 1339).records[0].table;
assert.equal(pos.count, POSITION_MAX + 1);
assert.equal(pos.min, 0);
assert.equal(pos.max, POSITION_MAX);
assert.equal(pos.unique, POSITION_MAX + 1);
assert.equal(doc.descriptors.find((r) => r.ui === 1803).records.length, 0);

const payloadBits = 4 * 3 + 8 + 11 * 3 + 4 * 5 + 4 * 5 + 3 * 4 + 3 * 4;
assert.equal(payloadBits, 117);
assert.equal(FIELD_BITS, 16 + 8 + payloadBits);
assert.equal(FIELD_BITS + PAD_BITS + CRC_BITS, USED_BYTES * 8);
assert.ok(USED_BYTES <= RECORD_BYTES);
const available = RECORD_BYTES * 8;
assert.equal(available, 208);
assert.ok(FIELD_BITS + PAD_BITS + CRC_BITS <= available);

function roundTrip(profile) {
  const bytes = encode(profile);
  assert.equal(bytes.length, RECORD_BYTES);
  const back = decode(bytes);
  assert.deepEqual(back, profile);
  const mirror = mirrorFromProfile(profile);
  assert.equal(mirror.length, MIRROR_BYTES);
  assert.deepEqual(profileFromMirror(mirror), profile);
  assert.deepEqual(decode(encode(profileFromMirror(mirror))), profile);
}

roundTrip(PROFILE_A);
for (const z of ZONE) {
  for (const bank of BANKS) {
    const p = structuredClone(PROFILE_A);
    p.zone[bank] = z;
    roundTrip(p);
  }
}
for (const v of [0, POSITION_MAX]) {
  for (const bank of BANKS) {
    const p = structuredClone(PROFILE_A);
    p.position[bank] = v;
    roundTrip(p);
  }
}
for (const size of [0, 255]) {
  const p = structuredClone(PROFILE_A);
  p.size = size;
  roundTrip(p);
}
for (let i = 0; i < 10; i++) {
  const table = i % 2 === 0 ? DIM_V : DIM_H;
  for (const v of table) {
    const p = structuredClone(PROFILE_A);
    p.dim[i] = v;
    roundTrip(p);
  }
}
for (let i = 0; i < 8; i++) {
  const table = i % 2 === 0 ? STEP_V : STEP_H;
  for (const v of table) {
    const p = structuredClone(PROFILE_A);
    p.step[i] = v;
    roundTrip(p);
  }
}

assert.equal(decode(new Uint8Array(RECORD_BYTES)), null);
assert.equal(decode(new Uint8Array(RECORD_BYTES).fill(0xff)), null);
const stock = new Uint8Array(RECORD_BYTES);
for (let i = 0; i < RECORD_BYTES; i += 2) {
  stock[i] = 0x80;
  stock[i + 1] = 0x0c;
}
assert.equal(decode(stock), null);
assert.equal(readMarker(stock), 0x0c80);
assert.notEqual(MARKER, 0);
assert.notEqual(MARKER, 0x0c80);

const good = encode(PROFILE_A);
for (let bit = 0; bit < RECORD_BYTES * 8; bit++) {
  const flipped = Uint8Array.from(good);
  flipped[bit >> 3] ^= 1 << (bit & 7);
  assert.equal(decode(flipped), null, 'bit ' + bit);
}

function readMarker(bytes) {
  return bytes[0] | (bytes[1] << 8);
}

const badZone = structuredClone(PROFILE_A);
badZone.zone[1] = 4;
assert.throws(() => encode(badZone), RangeError);
const badPos = structuredClone(PROFILE_A);
badPos.position[1] = POSITION_MAX + 1;
assert.throws(() => encode(badPos), RangeError);
const badDim = structuredClone(PROFILE_A);
badDim.dim[1] = 2;
assert.throws(() => encode(badDim), RangeError);
const badStep = structuredClone(PROFILE_A);
badStep.step[0] = 8;
assert.throws(() => encode(badStep), RangeError);

const crafted = Uint8Array.from(good);
// Zone bank 1 is the first 4-bit code, at bit 24. Code 10 is not in the table.
const zoneBit = 24;
for (let i = 0; i < 4; i++) {
  const bit = zoneBit + i;
  const want = (10 >> i) & 1;
  const has = (crafted[bit >> 3] >> (bit & 7)) & 1;
  if (has !== want) crafted[bit >> 3] ^= 1 << (bit & 7);
}
const crc = crc16(crafted.subarray(0, USED_BYTES - 2));
crafted[18] = crc & 0xff;
crafted[19] = (crc >> 8) & 0xff;
assert.equal(decode(crafted), null);

const badVersion = Uint8Array.from(good);
badVersion[2] = VERSION === 1 ? 2 : 1;
const crc2 = crc16(badVersion.subarray(0, USED_BYTES - 2));
badVersion[18] = crc2 & 0xff;
badVersion[19] = (crc2 >> 8) & 0xff;
assert.equal(decode(badVersion), null);

console.log(JSON.stringify({
  ok: true,
  payload_bits: payloadBits,
  field_bits: FIELD_BITS,
  pad_bits: PAD_BITS,
  crc_bits: CRC_BITS,
  used_bytes: USED_BYTES,
  available_bits: available,
  spare_bits: available - (FIELD_BITS + PAD_BITS + CRC_BITS),
  marker: MARKER,
  version: VERSION,
  position_max: POSITION_MAX,
}));
